import { readFileSync } from 'fs';
import { join } from 'path';
import { TOKEN_TAILS_HELD_WALLETS } from './shelter-onchain.config';
import { CHAINS, WALLETS } from './wallet.config';

/*
 * wallet.config.ts is generated by `fund a:ingest` (and `fund a:backend-deployments`) from the same
 * records that write the client's public deployment lists. This spec keeps the two in sync: every split
 * the client lists is in the backend config and the other way round, with the same token symbol.
 */
const CLIENT = join(__dirname, '..', '..', '..', '..', 'client', 'public', 'shelter-payouts');
const list = (file: string): any[] => JSON.parse(readFileSync(join(CLIENT, file), 'utf8'));

describe('wallet.config.ts (generated) stays in sync with the client deployment lists', () => {
    for (const [network, file] of [
        ['mainnet', 'deployments.json'],
        ['testnet', 'testnet-deployments.json'],
    ] as const) {
        it(`${network}: the same ShelterSplit instances, tokens and deploy txs`, () => {
            const client = list(file)
                .map(
                    d =>
                        `${d.chainId}:${String(d.address).toLowerCase()}:${d.symbol || d.token || 'USDC'}:${d.tx || ''}`
                )
                .sort();
            const backend = Object.values(CHAINS)
                .filter(c => c.network === network)
                .flatMap(c => [...(c.split ? [c.split] : []), ...c.otherSplits].map(s => ({ c, s })))
                .map(({ c, s }) => `${c.chainId}:${s.address}:${s.token.symbol}:${s.deployTx || ''}`)
                .sort();
            expect(backend).toEqual(client);
        });
    }

    it('names one default split per chain, never a second token (EURC)', () => {
        for (const c of Object.values(CHAINS)) {
            if (!c.split) continue;
            expect(c.split.token.symbol).not.toBe('EURC');
            expect(c.token.symbol).toBe(c.split.token.symbol);
        }
    });

    it('carries Pink Paw, the testnet treasury and hot wallet, and the held wallet list agrees', () => {
        expect(WALLETS.mainnet.pinkPaw!.toLowerCase()).toBe(TOKEN_TAILS_HELD_WALLETS[0]);
        expect(WALLETS.testnet.treasury).toMatch(/^0x[0-9a-fA-F]{40}$/);
        expect(WALLETS.testnet.donateHot).toMatch(/^0x[0-9a-fA-F]{40}$/);
    });
});
